using System.Collections.Generic;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CurrentCorruptedAnimals", menuName = "Data/Battle/Corrupted Animals/Current Corrupted Animals")]
public class CurrentCorruptedAnimals : ScriptableObject
{
	public List<GameObject> activeCorruptedAnimals = new List<GameObject>();

	[SerializeField]
	private MapHandler mapHandler;

	public void ClearActiveCorruptedAnimals()
	{
		Debug.Log("!!!!!!!!!!!!!!!!!!!!!!!!ClearActiveCorruptedAnimals!!!!!!!!!!!!!!!!!!");
		activeCorruptedAnimals.Clear();
	}

	public void OnReset()
	{
		ClearActiveCorruptedAnimals();
	}

	public bool IsAnyEnemyActive()
	{
		if (mapHandler.BossBattle || mapHandler.CorruptedOracleBattle)
		{
			if (mapHandler.BossBattle && mapHandler.IsOnAstreasHeart)
			{
				if (activeCorruptedAnimals.Count == 3)
				{
					int num = 0;
					for (int i = 0; i < activeCorruptedAnimals.Count; i++)
					{
						CorruptedAnimalCorruptionStats component = activeCorruptedAnimals[i].GetComponent<CorruptedAnimalCorruptionStats>();
						if (component.IsDefeated() || component.InfinityCorruption)
						{
							num++;
						}
					}
					return num < 3;
				}
				return activeCorruptedAnimals.Count > 0;
			}
			return GetCorruptionSource() != null;
		}
		return activeCorruptedAnimals.Count > 0;
	}

	public void StoreAllCorruptedAnimals()
	{
		Debug.Log("StoreAllCorruptedAnimals");
		for (int i = 0; i < activeCorruptedAnimals.Count; i++)
		{
			if (activeCorruptedAnimals[i] != null)
			{
				activeCorruptedAnimals[i].GetComponent<UnitsDiceActivation>().StoreDice();
				activeCorruptedAnimals[i].GetComponent<UnitEffects>().ActivateOnRemoveEffectEndOfBattleCallback();
				ReferenceSingleton<PoolHandler>.Instance.StoreObject(activeCorruptedAnimals[i]);
			}
		}
		ClearActiveCorruptedAnimals();
	}

	public bool IsAnyEnemyWithStartOfBattleSFXPlayIt()
	{
		for (int i = 0; i < activeCorruptedAnimals.Count; i++)
		{
			if (activeCorruptedAnimals[i].GetComponent<CorruptedAnimalInitializer>().EnemyHasStartOfBattleSFXPlayIt())
			{
				return true;
			}
		}
		return false;
	}

	public bool IsAnyEnemyWithStartOfBattleSFX()
	{
		for (int i = 0; i < activeCorruptedAnimals.Count; i++)
		{
			if (activeCorruptedAnimals[i].GetComponent<CorruptedAnimalInitializer>().EnemyHasStartOfBattleSFX())
			{
				return true;
			}
		}
		return false;
	}

	public GameObject GetCorruptionSource()
	{
		GameObject result = null;
		for (int i = 0; i < activeCorruptedAnimals.Count; i++)
		{
			if (activeCorruptedAnimals[i].GetComponent<CorruptedAnimalCorruptionStats>().CorruptedAnimalData.CorruptionSource)
			{
				result = activeCorruptedAnimals[i];
			}
		}
		return result;
	}

	public List<GameObject> GetCorruptedAnimalsNotCorruptionSource()
	{
		List<GameObject> list = new List<GameObject>();
		for (int i = 0; i < activeCorruptedAnimals.Count; i++)
		{
			if (!activeCorruptedAnimals[i].GetComponent<CorruptedAnimalCorruptionStats>().CorruptedAnimalData.CorruptionSource)
			{
				list.Add(activeCorruptedAnimals[i]);
			}
		}
		return list;
	}

	public GameObject GetEnemyWithLowestCorruption()
	{
		List<GameObject> list = new List<GameObject>();
		float num = 100000f;
		for (int i = 0; i < activeCorruptedAnimals.Count; i++)
		{
			CorruptedAnimalCorruptionStats component = activeCorruptedAnimals[i].GetComponent<CorruptedAnimalCorruptionStats>();
			if (component.CurrentCorruption < num && component.CurrentCorruption > 0f)
			{
				num = component.CurrentCorruption;
				list.Clear();
				list.Add(activeCorruptedAnimals[i]);
			}
			else if (component.CurrentCorruption == num)
			{
				list.Add(activeCorruptedAnimals[i]);
			}
		}
		GameObject result = null;
		if (list.Count > 0)
		{
			result = list.PickRandom();
		}
		return result;
	}

	public GameObject GetEnemyWithLowestCorruptionNotCorruptionSource()
	{
		List<GameObject> list = new List<GameObject>();
		float num = 100000f;
		for (int i = 0; i < activeCorruptedAnimals.Count; i++)
		{
			CorruptedAnimalCorruptionStats component = activeCorruptedAnimals[i].GetComponent<CorruptedAnimalCorruptionStats>();
			if (!component.CorruptedAnimalData.CorruptionSource)
			{
				if (component.CurrentCorruption < num)
				{
					num = component.CurrentCorruption;
					list.Clear();
					list.Add(activeCorruptedAnimals[i]);
				}
				else if (component.CurrentCorruption == num)
				{
					list.Add(activeCorruptedAnimals[i]);
				}
			}
		}
		GameObject result = null;
		if (list.Count > 0)
		{
			result = list.PickRandom();
		}
		return result;
	}

	public GameObject GetEnemyWithMostCorruption()
	{
		List<GameObject> list = new List<GameObject>();
		float num = -1f;
		for (int i = 0; i < activeCorruptedAnimals.Count; i++)
		{
			CorruptedAnimalCorruptionStats component = activeCorruptedAnimals[i].GetComponent<CorruptedAnimalCorruptionStats>();
			if (component.CurrentCorruption > num)
			{
				num = component.CurrentCorruption;
				list.Clear();
				list.Add(activeCorruptedAnimals[i]);
			}
			else if (component.CurrentCorruption == num)
			{
				list.Add(activeCorruptedAnimals[i]);
			}
		}
		GameObject result = null;
		if (list.Count > 0)
		{
			result = list.PickRandom();
		}
		return result;
	}

	public bool IsCorruptedAnimalWithSilencingAuraWithActivation()
	{
		for (int i = 0; i < activeCorruptedAnimals.Count; i++)
		{
			if (activeCorruptedAnimals[i].GetComponent<CorruptedAnimalEffects>().IsSilencingAuraActiveWithActivation())
			{
				return true;
			}
		}
		return false;
	}

	public bool IsCorruptedAnimalWithSilencingAura()
	{
		for (int i = 0; i < activeCorruptedAnimals.Count; i++)
		{
			if (activeCorruptedAnimals[i].GetComponent<CorruptedAnimalEffects>().IsSilencingAuraActive(feedback: false))
			{
				return true;
			}
		}
		return false;
	}

	public void PlayFeedbackOfCorruptedAnimalWithSilencingAura()
	{
		for (int i = 0; i < activeCorruptedAnimals.Count; i++)
		{
			activeCorruptedAnimals[i].GetComponent<CorruptedAnimalEffects>().IsSilencingAuraActive(feedback: true);
		}
	}

	public int GetCorruptedAnimalIndex(GameObject corruptedAnimalGo)
	{
		return activeCorruptedAnimals.IndexOf(corruptedAnimalGo);
	}

	public bool IsAllEnemiesDefeated()
	{
		for (int i = 0; i < activeCorruptedAnimals.Count; i++)
		{
			if (!activeCorruptedAnimals[i].GetComponent<CorruptionStats>().IsDefeated())
			{
				return false;
			}
		}
		return true;
	}

	public void InstantlyDefeatAllMinions()
	{
		List<GameObject> corruptedAnimalsNotCorruptionSource = GetCorruptedAnimalsNotCorruptionSource();
		for (int i = 0; i < corruptedAnimalsNotCorruptionSource.Count; i++)
		{
			corruptedAnimalsNotCorruptionSource[i].GetComponent<CorruptedAnimalCorruptionStats>().InstantlyDefeatEnemy(minionDefeatedByBossDefeat: true);
		}
	}

	public bool IsAnyEnemyWithEffect(Effect effect)
	{
		for (int i = 0; i < activeCorruptedAnimals.Count; i++)
		{
			if (activeCorruptedAnimals[i].GetComponent<UnitEffects>().IsEffectActive(effect, activateFeedback: false))
			{
				return true;
			}
		}
		return false;
	}

	public int GetAmountOfEnemiesWithEffect(Effect effect)
	{
		int num = 0;
		for (int i = 0; i < activeCorruptedAnimals.Count; i++)
		{
			if (activeCorruptedAnimals[i].GetComponent<UnitEffects>().IsEffectActive(effect, activateFeedback: false))
			{
				num++;
			}
		}
		return num;
	}

	public List<DiceInstance> GetEnemiesDiceInstances()
	{
		List<DiceInstance> list = new List<DiceInstance>();
		for (int i = 0; i < activeCorruptedAnimals.Count; i++)
		{
			list.AddRange(activeCorruptedAnimals[i].GetComponent<CorruptedAnimalActivation>().GetDiceInstancesToRoll());
		}
		return list;
	}

	public bool IsAphoticInstinctActiveAndWithNoDoom()
	{
		for (int i = 0; i < activeCorruptedAnimals.Count; i++)
		{
			if (activeCorruptedAnimals[i].GetComponent<CorruptedAnimalEffects>().IsAphoticInstinctActiveAndWithNoDoom())
			{
				return true;
			}
		}
		return false;
	}

	public GameObject IsCorruptedAnimalWithElectrostaticField()
	{
		for (int i = 0; i < activeCorruptedAnimals.Count; i++)
		{
			if (activeCorruptedAnimals[i].GetComponent<UnitEffects>().IsElectrostaticField())
			{
				return activeCorruptedAnimals[i];
			}
		}
		return null;
	}

	public GameObject IsCorruptedAnimalWithHornetDust()
	{
		for (int i = 0; i < activeCorruptedAnimals.Count; i++)
		{
			if (activeCorruptedAnimals[i].GetComponent<UnitEffects>().IsHornetDust())
			{
				return activeCorruptedAnimals[i];
			}
		}
		return null;
	}

	public bool IsAnyEnemyWithAffliction()
	{
		for (int i = 0; i < activeCorruptedAnimals.Count; i++)
		{
			if (activeCorruptedAnimals[i].GetComponent<UnitEffects>().IsAfflictionActiveGetAmount() > 0)
			{
				return true;
			}
		}
		return false;
	}

	public int GetEnemiesWithAtLeastXAfflictionAmount(int afflictionToCompareAmount)
	{
		int num = 0;
		for (int i = 0; i < activeCorruptedAnimals.Count; i++)
		{
			if (activeCorruptedAnimals[i].GetComponent<UnitEffects>().IsAfflictionActiveGetAmount() >= afflictionToCompareAmount)
			{
				num++;
			}
		}
		return num;
	}

	public bool IsDiceGorgerActiveWithAtLeastOneAmount()
	{
		for (int i = 0; i < activeCorruptedAnimals.Count; i++)
		{
			if (activeCorruptedAnimals[i].GetComponent<CorruptedAnimalEffects>().IsDiceGorgerActiveWithAtLeastOneAmount())
			{
				return true;
			}
		}
		return false;
	}

	public int IsAnyWithEnemyDuskyConversionGetAmount()
	{
		for (int i = 0; i < activeCorruptedAnimals.Count; i++)
		{
			int num = activeCorruptedAnimals[i].GetComponent<CorruptedAnimalEffects>().IsDuskyConversionActive();
			if (num > 0)
			{
				return num;
			}
		}
		return 0;
	}

	public void IsAnyWithEnemyDeepnessPresenceWithActivation()
	{
		for (int i = 0; i < activeCorruptedAnimals.Count; i++)
		{
			activeCorruptedAnimals[i].GetComponent<CorruptedAnimalEffects>().IsDeepnessPresenceActiveWithActivation();
		}
	}

	public bool IsAnyWithEnemyCursedSandsCheckCursedSands(DiceInstance diceInstance)
	{
		for (int i = 0; i < activeCorruptedAnimals.Count; i++)
		{
			if (activeCorruptedAnimals[i].GetComponent<CorruptedAnimalEffects>().IsEnemyCursedSandsCheckCursedSands(diceInstance))
			{
				return true;
			}
		}
		return false;
	}

	public List<GameObject> GetEnemiesNotInfinityCorruptionAndNotEffectOwner(GameObject effectOwner)
	{
		List<GameObject> list = new List<GameObject>();
		for (int i = 0; i < activeCorruptedAnimals.Count; i++)
		{
			GameObject gameObject = activeCorruptedAnimals[i];
			if (gameObject != effectOwner && !gameObject.GetComponent<CorruptedAnimalCorruptionStats>().InfinityCorruption)
			{
				list.Add(gameObject);
			}
		}
		return list;
	}
}
